arguments.command:
cd /tmp/sv-41fb3c9cd1ee4bd9aa991d62e6bb407f && \
# Look up each address in the dynamic symbol table
# Addresses from the tombstone: 0x222098, 0x2241ac, 0x1abc80, 0x1abd14, 0x16dfa4, 0x16db6c, 0x16de04
for addr in 0x222098 0x2241ac 0x1abc80 0x1abd14 0x16dfa4 0x16db6c 0x16de04; do
  echo -n "#$addr: "
  readelf --dyn-syms libmonosgen-2.0.so 2>/dev/null | awk -v addr="$addr" '
    BEGIN { target = strtonum(addr); best_name = ""; best_addr = 0; best_size = 0 }
    /FUNC/ {
      sym_addr = strtonum("0x" $2);
      sym_size = strtonum($3);
      if (sym_addr <= target && sym_addr > best_addr) {
        best_addr = sym_addr;
        best_name = $NF;
        best_size = sym_size;
      }
    }
    END {
      if (best_name != "") {
        printf "%s+0x%x (size=0x%x)\n", best_name, target - best_addr, best_size
      } else {
        print "unknown"
      }
    }
  '
done

