cd /tmp/sv-41fb3c9cd1ee4bd9aa991d62e6bb407f && \
# The symbols are truncated. Let me get the full names
for addr in 0x222098 0x2241ac 0x1abc80 0x1abd14 0x16dfa4 0x16db6c 0x16de04; do
  echo -n "pc $addr => "
  readelf --wide --dyn-syms libmonosgen-2.0.so 2>/dev/null | awk -v addr="$addr" '
    BEGIN { target = strtonum(addr); best_name = ""; best_addr = 0 }
    /FUNC/ {
      sym_addr = strtonum("0x" $2);
      if (sym_addr <= target && sym_addr > best_addr) {
        best_addr = sym_addr;
        best_name = $8;
        for(i=9;i<=NF;i++) best_name = best_name " " $i;
      }
    }
    END {
      if (best_name != "") printf "%s+0x%x\n", best_name, target - best_addr
      else print "unknown"
    }
  '
done

