arguments.command:
cd /tmp/sv-41fb3c9cd1ee4bd9aa991d62e6bb407f && \
# Let me find the actual containing function (where addr is within [sym_addr, sym_addr+size])
for addr in 0x222098 0x2241ac 0x1abc80 0x1abd14 0x16dfa4 0x16db6c 0x16de04; do
  echo -n "pc $addr => "
  readelf --wide --dyn-syms libmonosgen-2.0.so 2>/dev/null | awk -v addr="$addr" '
    BEGIN { target = strtonum(addr) }
    /FUNC/ && $3+0 > 0 {
      sym_addr = strtonum("0x" $2);
      sym_size = strtonum($3);
      if (sym_addr <= target && target < sym_addr + sym_size) {
        printf "%s+0x%x\n", $8, target - sym_addr
        found = 1
        exit
      }
    }
    END { if (!found) print "(not in any exported symbol range)" }
  '
done

